@app.route('/patients',methods=['GET','POST'])
@roles('Administrateur','Réceptionniste','Direction')
def patients():
 c=con()
 if request.method=='POST':
  try:
   t=now()

   # Génération automatique du numéro patient
   last=c.execute(
    "SELECT patient_number FROM patients WHERE patient_number LIKE ? ORDER BY id DESC LIMIT 1",
    ('PAT%',)
   ).fetchone()

   if last and last['patient_number']:
    try:
     num=int(last['patient_number'].replace('PAT',''))
    except ValueError:
     num=0
   else:
    num=0

   patient_number=f'PAT{num+1:06d}'

   cur=c.execute(
    'INSERT INTO patients(patient_number,last_name,post_name,first_name,sex,birth_date,birth_place,address,phone,profession,admin_info,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)',
    (
     patient_number,
     request.form['last_name'],
     request.form.get('post_name'),
     request.form['first_name'],
     request.form['sex'],
     request.form.get('birth_date') or None,
     request.form.get('birth_place'),
     request.form.get('address'),
     request.form.get('phone'),
     request.form.get('profession'),
     request.form.get('admin_info'),
     t,
     t
    )
   )

   pid=cur.lastrowid

   c.execute(
    'INSERT INTO medical_records(patient_id,created_at,updated_at) VALUES(?,?,?)',
    (pid,t,t)
   )

   c.commit()
   write_audit('CRÉATION PATIENT','RÉCEPTION','SUCCÈS','patients',pid)
   flash(f'Patient {patient_number} enregistré.','success')

  except (sqlite3.IntegrityError, PGIntegrityError):
   c.rollback()
   flash('Impossible d’enregistrer le patient. Vérifiez les données saisies.','danger')

 rows=c.execute(
  'SELECT * FROM patients ORDER BY id DESC LIMIT 200'
 ).fetchall()

 c.close()

 body='''<h1>Patients</h1>
<div class="card">
<form method="post">
<input type="hidden" name="_csrf" value="{{csrf}}">
<div class="formgrid">

<div>
<label>N° patient</label>
<input value="Généré automatiquement" readonly>
</div>

<div>
<label>Nom</label>
<input name="last_name" required>
</div>

<div>
<label>Post-nom</label>
<input name="post_name">
</div>

<div>
<label>Prénom</label>
<input name="first_name" required>
</div>

<div>
<label>Sexe</label>
<select name="sex" required>
<option value="">Sélectionner</option>
<option value="F">F</option>
<option value="M">M</option>
</select>
</div>

<div>
<label>Date de naissance</label>
<input name="birth_date" type="date">
</div>

<div>
<label>Lieu de naissance</label>
<input name="birth_place">
</div>

<div>
<label>Adresse</label>
<input name="address">
</div>

<div>
<label>Téléphone</label>
<input name="phone">
</div>

<div>
<label>Profession</label>
<input name="profession">
</div>

<div>
<label>Informations administratives nécessaires</label>
<input name="admin_info">
</div>

</div>
<br>
<button>Enregistrer le patient</button>
</form>
</div>

<div class="card">
<table>
<tr>
<th>N°</th>
<th>Identité</th>
<th>Sexe</th>
<th>Naissance</th>
<th>Téléphone</th>
</tr>

{% for p in rows %}
<tr>
<td>{{p.patient_number}}</td>
<td>{{p.last_name}} {{p.post_name or ''}} {{p.first_name}}</td>
<td>{{p.sex}}</td>
<td>{{p.birth_date or ''}}</td>
<td>{{p.phone or ''}}</td>
</tr>
{% endfor %}

</table>
</div>'''

 return page('Patients',body,rows=rows)

