@app.route('/pharmacy',methods=['GET','POST'])
@roles('Administrateur','Pharmacien','Médecin','Direction')
def pharmacy():
 c=con()
 if request.method=='POST':
  action=request.form.get('action')
  if action=='medicine':
   try:
    purchase_price=float(request.form.get('purchase_price') or 0); sale_price=float(request.form.get('sale_price') or 0); quantity=float(request.form.get('quantity') or 0); minimum_threshold=float(request.form.get('minimum_threshold') or 0)
    if min(purchase_price,sale_price,quantity,minimum_threshold)<0: raise ValueError('negative')
    cur=c.execute('INSERT INTO medicines(code,name,form,dosage,category,supplier,purchase_price,sale_price,available_quantity,minimum_threshold,expiration_date,lot_number,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)',(request.form['code'],request.form['name'],request.form.get('form'),request.form.get('dosage'),request.form.get('category'),request.form.get('supplier'),purchase_price,sale_price,quantity,minimum_threshold,request.form.get('expiration_date'),request.form.get('lot_number'),now(),now()))
    c.commit();write_audit('CRÉATION MÉDICAMENT','PHARMACIE','SUCCÈS','medicines',cur.lastrowid);flash('Médicament enregistré.','success')
   except (ValueError,TypeError,sqlite3.IntegrityError,PGIntegrityError):
    c.rollback();flash('Médicament invalide ou code déjà utilisé.','danger')
  elif action=='movement':
   try:
    mid=int(request.form['medicine_id']); q=float(request.form['quantity']); typ=request.form['movement_type']
    if q<=0 or typ not in ('Entrée','Sortie','Délivrance'): raise ValueError('movement')
    m=c.execute('SELECT * FROM medicines WHERE id=?',(mid,)).fetchone()
    if not m: raise ValueError('medicine')
    patient_id=request.form.get('patient_id') or None; consultation_id=request.form.get('consultation_id') or None; prescription_id=request.form.get('prescription_id') or None
    reference=request.form.get('reference') or None; reason=request.form.get('reason') or None; supplier=request.form.get('supplier') or None
    if typ=='Entrée':
     supplier=supplier or m['supplier']
     if not supplier: raise ValueError('supplier')
    if typ in ('Sortie','Délivrance') and not patient_id: raise ValueError('patient')
    if typ=='Délivrance' and not prescription_id: raise ValueError('prescription')
    if typ!='Entrée' and float(m['available_quantity'] or 0)<q: raise ValueError('stock')
    if patient_id and not c.execute('SELECT id FROM patients WHERE id=?',(patient_id,)).fetchone(): raise ValueError('patient')
    if consultation_id:
     cc=c.execute('SELECT id,patient_id FROM consultations WHERE id=?',(consultation_id,)).fetchone()
     if not cc or int(cc['patient_id'])!=int(patient_id): raise ValueError('consultation')
    if prescription_id:
     pr=c.execute('SELECT p.id,p.patient_id,p.consultation_id,pi.medicine_id FROM prescriptions p JOIN prescription_items pi ON pi.prescription_id=p.id WHERE p.id=? AND pi.medicine_id=?',(prescription_id,mid)).fetchone()
     if not pr or int(pr['patient_id'])!=int(patient_id): raise ValueError('prescription')
     if consultation_id and pr['consultation_id'] and int(pr['consultation_id'])!=int(consultation_id): raise ValueError('consultation')
     consultation_id=pr['consultation_id']
    unit_price=float(m['purchase_price'] or 0) if typ=='Entrée' else float(m['sale_price'] or 0); total_amount=round(q*unit_price,4); delta=q if typ=='Entrée' else -q
    if typ=='Délivrance' and not reason: reason='Délivrance sur prescription'
    c.execute('UPDATE medicines SET available_quantity=available_quantity+?,updated_at=? WHERE id=?',(delta,now(),mid))
    cur=c.execute('INSERT INTO stock_movements(medicine_id,movement_type,quantity,unit_price,total_amount,reference,reason,supplier,patient_id,consultation_id,prescription_id,user_id,movement_date) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)',(mid,typ,q,unit_price,total_amount,reference,reason,supplier,patient_id,consultation_id,prescription_id,session['uid'],now()))
    c.commit();write_audit('MOUVEMENT STOCK','PHARMACIE','SUCCÈS','stock_movements',cur.lastrowid);flash(f'Mouvement enregistré. Total : {total_amount:.4f}.','success')
   except (ValueError,TypeError,sqlite3.IntegrityError,PGIntegrityError):
    c.rollback();flash('Mouvement invalide. Vérifiez le patient, la consultation, la prescription, le fournisseur, la quantité et le stock.','danger')
 meds=c.execute('SELECT * FROM medicines ORDER BY name').fetchall()
 pats=c.execute('SELECT id,patient_number,last_name,first_name FROM patients ORDER BY last_name,first_name').fetchall()
 consultation_rows=c.execute('SELECT c.id,c.patient_id,c.consultation_date,p.patient_number,p.last_name,p.first_name FROM consultations c JOIN patients p ON p.id=c.patient_id ORDER BY c.id DESC LIMIT 200').fetchall()
 prescription_rows=c.execute('SELECT p.id,p.patient_id,p.consultation_id,p.prescription_date,pt.patient_number,pt.last_name,pt.first_name,pi.medicine_id,pi.medicine_name,pi.dosage,pi.frequency,pi.duration FROM prescriptions p JOIN patients pt ON pt.id=p.patient_id JOIN prescription_items pi ON pi.prescription_id=p.id ORDER BY p.id DESC LIMIT 300').fetchall()
 moves=c.execute('SELECT s.*,m.code,m.name,p.patient_number,p.last_name,p.first_name,u.username FROM stock_movements s JOIN medicines m ON m.id=s.medicine_id LEFT JOIN patients p ON p.id=s.patient_id LEFT JOIN users u ON u.id=s.user_id ORDER BY s.id DESC LIMIT 200').fetchall()
 c.close()
 body='''<h1>Pharmacie</h1><div class="card"><h3>Alertes de stock et péremption</h3>{% for m in meds %}{% if m.available_quantity<=m.minimum_threshold %}<div class="alert danger">Stock faible/rupture : {{m.code}} — {{m.name}} ({{m.available_quantity}})</div>{% endif %}{% if m.expiration_date and m.expiration_date < today %}<div class="alert danger">Produit expiré : {{m.code}} — {{m.name}} ({{m.expiration_date}})</div>{% endif %}{% endfor %}</div><div class="card"><h3>Gestion des médicaments</h3><form method="post"><input type="hidden" name="_csrf" value="{{csrf}}"><input type="hidden" name="action" value="medicine"><div class="formgrid"><div><label>Code</label><input name="code" required></div><div><label>Désignation</label><input name="name" required></div><div><label>Forme</label><input name="form"></div><div><label>Dosage</label><input name="dosage"></div><div><label>Catégorie</label><input name="category"></div><div><label>Fournisseur</label><input name="supplier"></div><div><label>Prix d'achat unitaire</label><input name="purchase_price" type="number" step="0.0001" min="0"></div><div><label>Prix de vente unitaire</label><input name="sale_price" type="number" step="0.0001" min="0"></div><div><label>Stock initial</label><input name="quantity" type="number" step="0.01" min="0"></div><div><label>Seuil minimum</label><input name="minimum_threshold" type="number" step="0.01" min="0"></div><div><label>Date d'expiration</label><input name="expiration_date" type="date"></div><div><label>Numéro de lot</label><input name="lot_number"></div></div><br><button>Enregistrer le médicament</button></form></div><div class="card"><h3>Entrée / sortie / délivrance</h3><p class="small">Une sortie ou une délivrance exige un patient. Une délivrance exige une prescription correspondant au médicament.</p><form method="post"><input type="hidden" name="_csrf" value="{{csrf}}"><input type="hidden" name="action" value="movement"><div class="formgrid"><div><label>Médicament</label><select name="medicine_id" id="pharmacy_medicine" required>{% for m in meds %}<option value="{{m.id}}">{{m.code}} — {{m.name}} | Stock : {{m.available_quantity}}</option>{% endfor %}</select></div><div><label>Type de mouvement</label><select name="movement_type" id="pharmacy_type" required><option>Entrée</option><option>Sortie</option><option>Délivrance</option></select></div><div><label>Quantité</label><input name="quantity" type="number" min="0.01" step="0.01" required></div><div><label>Patient</label><select name="patient_id" id="pharmacy_patient"><option value="">Non concerné</option>{% for p in pats %}<option value="{{p.id}}">{{p.patient_number}} — {{p.last_name}} {{p.first_name}}</option>{% endfor %}</select></div><div><label>Consultation</label><select name="consultation_id" id="pharmacy_consultation"><option value="">Aucune</option>{% for r in consultation_rows %}<option value="{{r.id}}" data-patient="{{r.patient_id}}">{{r.patient_number}} — {{r.last_name}} {{r.first_name}} — {{r.consultation_date}}</option>{% endfor %}</select></div><div><label>Prescription</label><select name="prescription_id" id="pharmacy_prescription"><option value="">Aucune</option>{% for r in prescription_rows %}<option value="{{r.id}}" data-patient="{{r.patient_id}}" data-medicine="{{r.medicine_id or ''}}">{{r.patient_number}} — {{r.last_name}} {{r.first_name}} — {{r.medicine_name}} — {{r.prescription_date}}</option>{% endfor %}</select></div><div><label>Fournisseur / provenance</label><input name="supplier"></div><div><label>Motif</label><input name="reason"></div><div><label>Référence</label><input name="reference"></div></div><br><button>Enregistrer le mouvement</button></form><script>(function(){const type=document.getElementById('pharmacy_type'),patient=document.getElementById('pharmacy_patient'),consult=document.getElementById('pharmacy_consultation'),presc=document.getElementById('pharmacy_prescription'),medicine=document.getElementById('pharmacy_medicine');function filter(){const pid=patient.value,mid=medicine.value;for(const o of consult.options){o.hidden=o.value!==''&&pid!==''&&o.dataset.patient!==pid}for(const o of presc.options){o.hidden=o.value!==''&&((pid!==''&&o.dataset.patient!==pid)||(mid!==''&&o.dataset.medicine!==mid))}const delivery=type.value==='Délivrance',out=delivery||type.value==='Sortie';patient.required=out;presc.required=delivery;if(!out){patient.value='';consult.value='';presc.value=''}}type.addEventListener('change',filter);patient.addEventListener('change',filter);medicine.addEventListener('change',filter);filter()})();</script></div><div class="card"><h3>État actuel du stock</h3><div style="overflow-x:auto"><table><tr><th>Code</th><th>Médicament</th><th>Stock</th><th>Seuil</th><th>Prix achat U.</th><th>Prix vente U.</th><th>Valeur achat</th><th>Valeur vente</th><th>Marge U.</th><th>Expiration</th><th>Lot</th></tr>{% for m in meds %}<tr><td>{{m.code}}</td><td><strong>{{m.name}}</strong></td><td>{{'%.2f'|format(m.available_quantity or 0)}}</td><td>{{'%.2f'|format(m.minimum_threshold or 0)}}</td><td>{{'%.4f'|format(m.purchase_price or 0)}}</td><td>{{'%.4f'|format(m.sale_price or 0)}}</td><td>{{'%.4f'|format((m.available_quantity or 0)*(m.purchase_price or 0))}}</td><td>{{'%.4f'|format((m.available_quantity or 0)*(m.sale_price or 0))}}</td><td>{{'%.4f'|format((m.sale_price or 0)-(m.purchase_price or 0))}}</td><td>{{m.expiration_date or ''}}</td><td>{{m.lot_number or ''}}</td></tr>{% endfor %}</table></div></div><div class="card"><h3>Historique détaillé des mouvements</h3><div style="overflow-x:auto"><table><tr><th>Date/heure</th><th>Type</th><th>Code</th><th>Médicament</th><th>Patient</th><th>Quantité</th><th>Prix U.</th><th>Total</th><th>Fournisseur</th><th>Motif</th><th>Référence</th><th>Utilisateur</th></tr>{% for r in moves %}<tr><td>{{r.movement_date}}</td><td>{{r.movement_type}}</td><td>{{r.code}}</td><td><strong>{{r.name}}</strong></td><td>{{(r.patient_number ~ ' — ' ~ r.last_name ~ ' ' ~ r.first_name) if r.patient_id else ''}}</td><td>{{'%.2f'|format(r.quantity or 0)}}</td><td>{{'%.4f'|format(r.unit_price or 0)}}</td><td><strong>{{'%.4f'|format(r.total_amount if r.total_amount is not none else ((r.quantity or 0)*(r.unit_price or 0)))}}</strong></td><td>{{r.supplier or ''}}</td><td>{{r.reason or ''}}</td><td>{{r.reference or ''}}</td><td>{{r.username or ''}}</td></tr>{% endfor %}</table></div></div>'''
 return page('Pharmacie',body,meds=meds,pats=pats,consultation_rows=consultation_rows,prescription_rows=prescription_rows,moves=moves,today=datetime.now().strftime('%Y-%m-%d'))


