    if paid:
     ex=c.execute('INSERT INTO expenses(reason,amount,supplier,user_id,expense_date) VALUES(?,?,?,?,?)',(f'Paie personnel #{ppid}',paid,None,session['uid'],now()));c.execute('UPDATE personnel_payments SET expense_id=? WHERE id=?',(ex.lastrowid,ppid))
